)


# ---------------------------------------------------------------------------
# Shared test data
# ---------------------------------------------------------------------------

PALINDROMES = [
    "MALAYALAM",
    "rotor",
    "level",
    "A",
    "BB",
    "amanaplanacanalpanama",
]

NON_PALINDROMES = [
    "String",
    "ABC",
    "abcdba",
    "AB",
]


# ---------------------------------------------------------------------------
# is_palindrome
