"""Tests for the word_occurrence function."""

from collections import Counter

import pytest

from word_occurrence import word_occurrence


class TestWordOccurrence:
    """Test suite for word_occurrence."""

    def test_happy_path_counts_each_word(self):
        """Test that a normal sentence returns correct per-word counts."""
        sentence = "a b A b c b d b d e f e g e h e i e j e 0"
        result = word_occurrence(sentence)

        expected = Counter(sentence.split())
        assert dict(result) == dict(expected)

    def test_single_word(self):
        """Test that a single-word sentence returns a count of one."""
        result = word_occurrence("hello")
        assert dict(result) == {"hello": 1}

    def test_repeated_single_word(self):
        """Test that a sentence with one repeated word counts correctly."""
        result = word_occurrence("word word word")
        assert dict(result) == {"word": 3}

    def test_multiple_spaces_are_collapsed(self):
        """Test that consecutive spaces do not produce empty-string keys."""
        result = word_occurrence("Two  spaces")
        assert dict(result) == {"Two": 1, "spaces": 1}

    def test_leading_and_trailing_whitespace(self):
        """Test that leading/trailing whitespace is ignored by split()."""
        result = word_occurrence("  leading trailing  ")
        assert dict(result) == {"leading": 1, "trailing": 1}

    def test_case_sensitive_counting(self):
        """Test that words differing only by case are counted separately."""
        result = word_occurrence("Hello hello HELLO")
        assert dict(result) == {"Hello": 1, "hello": 1, "HELLO": 1}

    def test_empty_string_returns_empty_dict(self):
        """Test that an empty string yields an empty dictionary."""
        result = word_occurrence("")
        assert dict(result) == {}

    def test_whitespace_only_returns_empty_dict(self):
        """Test that a whitespace-only string yields an empty dictionary."""
        result = word_occurrence("   \t  \n  ")
        assert dict(result) == {}

    def test_return_type_is_defaultdict(self):
        """Test that the return value is a defaultdict of int."""
        result = word_occurrence("a b a")
        assert isinstance(result, dict)
        # Accessing a missing key should return 0, not raise KeyError.
        assert result["missing"] == 0

    @pytest.mark.parametrize(
        "sentence, expected",
        [
            ("", {}),
            ("one", {"one": 1}),
            ("one two", {"one": 1, "two": 1}),
            ("one one", {"one": 2}),
            ("a b a b a", {"a": 3, "b": 2}),
            ("x  y   x", {"x": 2, "y": 1}),
        ],
    )
    def test_parametrized_counts(self, sentence, expected):
        """Test various inputs against their expected word counts."""
        assert dict(word_occurrence(sentence)) == expected

    def test_matches_counter_for_random_sentence(self):
        """Test that output matches collections.Counter for a mixed sentence."""
        sentence = "the quick brown fox jumps over the lazy dog the fox"
        result = word_occurrence(sentence)
        assert dict(result) == dict(Counter(sentence.split()))

import pytest

from decimal_to_binary import (
    decimal_to_binary_iterative,
    decimal_to_binary_recursive,
    decimal_to_binary_recursive_helper,
)


class TestDecimalToBinaryIterative:
    """Tests for decimal_to_binary_iterative."""

    @pytest.mark.parametrize(
        ("num", "expected"),
        [
            (0, "0b0"),
            (1, "0b1"),
            (2, "0b10"),
            (7, "0b111"),
            (35, "0b100011"),
            (1000, "0b1111101000"),
        ],
    )
    def test_positive_integers(self, num, expected):
        """Convert non-negative integers to their binary representation."""
        assert decimal_to_binary_iterative(num) == expected

    @pytest.mark.parametrize(
        ("num", "expected"),
        [
            (-1, "-0b1"),
            (-2, "-0b10"),
            (-7, "-0b111"),
            (-35, "-0b100011"),
        ],
    )
    def test_negative_integers(self, num, expected):
        """Convert negative integers to a prefixed negative binary string."""
        assert decimal_to_binary_iterative(num) == expected

    def test_float_raises_type_error(self):
        """A float input must raise a TypeError."""
        with pytest.raises(TypeError):
            decimal_to_binary_iterative(16.16)

    def test_string_raises_type_error(self):
        """A string input must raise a TypeError."""
        with pytest.raises(TypeError):
            decimal_to_binary_iterative("0xfffff")


class TestDecimalToBinaryRecursiveHelper:
    """Tests for decimal_to_binary_recursive_helper."""

    @pytest.mark.parametrize(
        ("decimal", "expected"),
        [
            (0, "0"),
            (1, "1"),
            (2, "10"),
            (72, "1001000"),
            (1000, "1111101000"),
        ],
    )
    def test_positive_integers(self, decimal, expected):
        """Convert positive integers to a binary string without prefix."""
        assert decimal_to_binary_recursive_helper(decimal) == expected

    def test_numeric_string_input(self):
        """A numeric string is coerced to int and converted."""
        assert decimal_to_binary_recursive_helper("72") == "1001000"

    def test_invalid_string_raises_value_error(self):
        """A non-numeric string must raise a ValueError."""
        with pytest.raises(ValueError):
            decimal_to_binary_recursive_helper("number")


class TestDecimalToBinaryRecursive:
    """Tests for decimal_to_binary_recursive."""

    @pytest.mark.parametrize(
        ("number", "expected"),
        [
            (0, "0b0"),
            (1, "0b1"),
            (40, "0b101000"),
            (1000, "0b1111101000"),
        ],
    )
    def test_positive_integers(self, number, expected):
        """Convert positive integers to a prefixed binary string."""
        assert decimal_to_binary_recursive(number) == expected

    @pytest.mark.parametrize(
        ("number", "expected"),
        [
            (-1, "-0b1"),
            (-40, "-0b101000"),
            (-1000, "-0b1111101000"),
        ],
    )
    def test_negative_integers(self, number, expected):
        """Convert negative integers to a negative-prefixed binary string."""
        assert decimal_to_binary_recursive(number) == expected

    @pytest.mark.parametrize(
        "number",
        [
            "40",
            " 40 ",
            "-40",
            " -40 ",
        ],
    )
    def test_string_inputs_with_whitespace(self, number):
        """String inputs (with optional whitespace/sign) are accepted."""
        expected = "0b101000" if number.strip().lstrip("-") == "40" else "-0b101000"
        assert decimal_to_binary_recursive(number) == expected

    def test_float_raises_value_error(self):
        """A float input must raise a ValueError."""
        with pytest.raises(ValueError):
            decimal_to_binary_recursive(40.8)

    def test_non_numeric_string_raises_value_error(self):
        """A non-numeric string must raise a ValueError."""
        with pytest.raises(ValueError):
            decimal_to_binary_recursive("forty")

    def test_empty_string_raises_value_error(self):
        """An empty string must raise a ValueError."""
        with pytest.raises(ValueError):
            decimal_to_binary_recursive("")

    def test_whitespace_only_raises_value_error(self):
        """A whitespace-only string must raise a ValueError."""
        with pytest.raises(ValueError):
            decimal_to_binary_recursive("   ")

